resource "local_sensitive_file" "cloud_init_ai_dev" {
  content = sensitive(templatefile("cloud_init.tftpl", {
    hostname           = "ai-dev"
    os_family          = "arch"
    tailscale_auth_key = local.proxmox_creds.tailscale_auth_key
  }))
  filename        = "${path.module}/files/ai-dev.cfg"
  file_permission = "0600"
}

resource "proxmox_virtual_environment_file" "cloud_init_ai_dev" {
  content_type = "snippets"
  datastore_id = "local"
  node_name    = local.proxmox_node
  overwrite    = true
  source_file {
    path      = local_sensitive_file.cloud_init_ai_dev.filename
    file_name = "ai-dev.yml"
    checksum  = local_sensitive_file.cloud_init_ai_dev.content_sha256
  }
}

resource "proxmox_virtual_environment_vm" "ai_dev" {
  depends_on          = [proxmox_virtual_environment_file.cloud_init_ai_dev]
  vm_id               = 110
  name                = "ai-dev"
  description         = "Managed by Terraform."
  node_name           = local.proxmox_node
  tags                = ["arch", "ai-dev"]
  bios                = "seabios"
  keyboard_layout     = "en-us"
  boot_order          = ["scsi0"]
  on_boot             = true
  reboot_after_update = true
  scsi_hardware       = "virtio-scsi-single"
  started             = true
  agent {
    enabled = true
    type    = "virtio"
  }
  operating_system {
    type = "l26"
  }
  clone {
    full      = false
    node_name = local.proxmox_node
    vm_id     = var.arch_cloud_template_vmid
  }
  cpu {
    cores   = 4
    sockets = 1
    type    = "host"
  }
  # 5 GiB produced ~60 OOM kills/month (tsc, bun, wezterm-mux); 7 GiB leaves the
  # host ~2 GiB headroom with TrueNAS at 10 GiB, docker-host at 8 GiB and ARC at 3 GiB.
  memory {
    dedicated = 7168
    floating  = 7168
  }
  initialization {
    datastore_id        = "local-zfs"
    interface           = "ide1"
    vendor_data_file_id = "local:snippets/ai-dev.yml"
    user_account {
      keys     = [var.ai_dev_ssh_public_key]
      username = "michael"
    }
    ip_config {
      ipv4 {
        address = "dhcp"
      }
      ipv6 {
        address = "dhcp"
      }
    }
  }
  serial_device {
    device = "socket"
  }
  disk {
    datastore_id = "local-zfs"
    discard      = "on"
    file_format  = "raw"
    interface    = "scsi0"
    # iothread on a local-zfs zvol can hang the host under bursty guest I/O.
    iothread  = false
    replicate = false
    size      = 150
  }
  network_device {
    bridge = "vmbr1"
    model  = "virtio"
  }
  lifecycle {
    ignore_changes  = [clone]
    prevent_destroy = true
  }
}

